static u32 crcupdate(u32 c,const u8*p,unsigned n){static const u32 t[]={0x00000000UL,0x1db71064UL,0x3b6e20c8UL,0x26d930acUL,0x76dc4190UL,0x6b6b51f4UL,0x4db26158UL,0x5005713cUL,0xedb88320UL,0xf00f9344UL,0xd6d6a3e8UL,0xcb61b38cUL,0x9b64c2b0UL,0x86d3d2d4UL,0xa00ae278UL,0xbdbdf21cUL};while(n--){c^=*p++;c=(c>>4)^t[(unsigned)c&15];c=(c>>4)^t[(unsigned)c&15];}return c;}
static void hex32(char*s,u32 n){unsigned i;const char*h="0123456789ABCDEF";for(i=0;i<8;i++){s[7-i]=h[(unsigned)n&15];n>>=4;}s[8]=0;}
static int num32(const char*s,u32*n,unsigned base){u32 v=0;unsigned d;if(!*s)return 0;while(*s&&*s!=';'&&*s!=' '&&*s!='\t'){char c=upper(*s++);if(c>='0'&&c<='9')d=c-'0';else if(c>='A'&&c<='F')d=c-'A'+10;else return 0;if(d>=base||v>(0xffffffffUL-d)/base)return 0;v=v*base+d;}*n=v;return 1;}
static int outputname(const char*s){unsigned a=0,b=0,dot=0;char base[9];const char*t=s;unsigned i=0;if(!*s||len(s)>12)return 0;while(*t&&*t!='.'&&i<8)base[i++]=upper(*t++);base[i]=0;if(eq(base,"CON")||eq(base,"PRN")||eq(base,"AUX")||eq(base,"NUL")||eq(base,"LLGET")||eq(base,"CLOCK$"))return 0;if(i==4&&(prefix(base,"COM")||prefix(base,"LPT"))&&base[3]>='0'&&base[3]<='9')return 0;while(*s){char c=upper(*s++);if(c=='.'){if(dot||!a)return 0;dot=1;continue;}if(!((c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='_'||c=='-'))return 0;if(!dot){if(++a>8)return 0;}else if(++b>3)return 0;}return !dot||b;}
static int parseurl(const char*s){unsigned i=0;char p[7];if(prefix(s,"https://")){say("HTTPS is unavailable; LLGet supports plain HTTP only.");return 0;}if(!prefix(s,"http://"))return 0;httpsflag=0;siteport=80;s+=7;while(*s&&*s!='/'&&*s!=':'&&*s!='?'&&*s!='#'){if(i==253||*s<=32||*s=='@'||*s=='[')return 0;site[i++]=*s++;}site[i]=0;if(!i)return 0;if(*s==':'){s++;i=0;while(*s&&*s!='/'&&*s!='?'){if(i==5||*s<'0'||*s>'9')return 0;p[i++]=*s++;}p[i]=0;if(!number(p,&siteport,10)||!siteport)return 0;}if(!*s)cp(requestpath,"/");else{if(len(s)>254)return 0;requestpath[0]=0;if(*s=='?')cp(requestpath,"/");cp(requestpath+len(requestpath),s);}for(i=0;requestpath[i];i++)if(requestpath[i]<=32||requestpath[i]=='#')return 0;return 1;}
static int sendstr(const char*s){unsigned n=len(s),z;while(n){z=n>256?256:n;if(net_send(s,z))return 0;s+=z;n-=z;}return 1;}
static int nextbyte(void){int n;while(pos==available){if(ended||failed)return -1;n=net_recv(receivebuf,blocksize);if(n<0){ended=1;if(word(3884)||word(3856)!=4)failed=1;return -1;}if(!n){if((u16)(net_ticks()-lasttick)>=timeout*18){failed=1;say("Receive timeout.");return -1;}continue;}lasttick=net_ticks();available=n;pos=0;}return receivebuf[pos++];}
static int readline(char*s,unsigned cap){unsigned n=0;int c;while((c=nextbyte())>=0){if(c=='\r'){if(nextbyte()!='\n')return 0;s[n]=0;return 1;}if(c=='\n'||!c||n+1==cap)return 0;s[n++]=(char)c;}return 0;}
static int flushdisk(int f){if(!used)return 1;if(wr(f,diskbuf,used)!=(int)used)return 0;used=0;return 1;}
static int bodybyte(int f,int c){if(c<0||total>=limit)return 0;diskbuf[used++]=(u8)c;crc=crcupdate(crc,diskbuf+used-1,1);total++;if(used==blocksize&&!flushdisk(f))return 0;if(!(total&8191UL))val("Downloaded bytes=",total);return 1;}
