 f=create("LLGET.$$$");if(f<0){say("Cannot create exclusive LLGET.$$$ staging file; existing file preserved.");goto done;}if(chunked){while(1){if(!readline(h,sizeof(h))||!num32(h,&chunk,16)||chunk>limit-total)goto done;if(!chunk){unsigned trailers=0;do{if(!readline(h,sizeof(h)))goto done;trailers+=len(h)+2;if(trailers>8192)goto done;}while(*h);good=1;break;}for(left=0;left<chunk;left++)if(!bodybyte(f,nextbyte()))goto done;if(nextbyte()!='\r'||nextbyte()!='\n')goto done;}}
